BEGIN READ ONLY; SET LOCAL statement_timeout='10s';
SELECT jsonb_build_object(
'captured_at',clock_timestamp(),'database',current_database(),
'migrations',(SELECT coalesce(jsonb_agg(jsonb_build_object('version',version,'name',name) ORDER BY version),'[]'::jsonb) FROM supabase_migrations.schema_migrations WHERE version >= '20261001'),
'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'kind',c.relkind) ORDER BY c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('account_deletion_barriers','adaptation_coverage','anime','anime_characters','anime_staff','anime_studios','anime_user_lists','artwork_materials','catalogue_units','chapters','club_activity_signals','club_members','club_membership_signals','concierge_events','detail_copy','episodes','external_links','feature_flag_overrides','feature_flags','home_publications','import_session_items','import_sessions','library_import_baselines','library_import_items','library_import_jobs','list_entry_tombstones','manga','manga_authors','manga_characters','manga_user_lists','mapping_revision_spans','mapping_revisions','mutation_receipts','mv_anime_trending','profiles','provider_entry_refs','realm_meta','release_events','series','series_enrichment_jobs','series_entry_spans','series_sections','streaming_services','theme_links','user_airing_next','user_series_intent','user_streaming_services')),
'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable) ORDER BY table_name,ordinal_position),'[]'::jsonb) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('account_deletion_barriers','adaptation_coverage','anime','anime_characters','anime_staff','anime_studios','anime_user_lists','artwork_materials','catalogue_units','chapters','club_activity_signals','club_members','club_membership_signals','concierge_events','detail_copy','episodes','external_links','feature_flag_overrides','feature_flags','home_publications','import_session_items','import_sessions','library_import_baselines','library_import_items','library_import_jobs','list_entry_tombstones','manga','manga_authors','manga_characters','manga_user_lists','mapping_revision_spans','mapping_revisions','mutation_receipts','mv_anime_trending','profiles','provider_entry_refs','realm_meta','release_events','series','series_enrichment_jobs','series_entry_spans','series_sections','streaming_services','theme_links','user_airing_next','user_series_intent','user_streaming_services')),
'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'identity_args',pg_get_function_identity_arguments(p.oid),'args',pg_get_function_arguments(p.oid),'return',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'md5',md5(p.prosrc)) ORDER BY p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('_apply_progress_mutations_for_user','_bridge_legacy_unit_v1','_fence_set_progress_status','_import_mutation_id','_queue_series_enrichment_v1','add_club_rail_item','apply_import_chunk_v1','apply_import_session','apply_progress_mutations_v1','apply_remove_mutations_v1','backfill_legacy_series_units_v1','backfill_series_enrichment_v1','batch_provider_availability_for_media_v2','batch_providers_for_media','browse_anime_page','browse_manga_page','cast_club_vote','catalogue_series_enrichment_delete_v1','catalogue_series_enrichment_trigger_v1','check_club_activity_since','check_email_exists','claim_series_enrichment_v1','club_disclosure_signal_v1','club_peer_display_name','club_shared_providers','collection_feed_page','collection_series_children_v1','collection_series_page_v1','count_friends_tracking','create_club','create_club_poll','create_club_rail','delete_title_comment','discover_bundle','enqueue_media_availability_refresh','enqueue_media_relation_refresh','fetch_because_you_rail','fetch_club_bundle','fetch_club_bundle_loading','fetch_daily_feature','fetch_friend_activity_for_title','fetch_my_clubs_enriched','fetch_my_clubs_loading','fetch_my_taste_profile','fetch_personalized_new_to_you','fetch_realm_hidden_gem','fetch_taste_deck_batch','fetch_tonight_shelf','finish_library_import_v1','finish_series_enrichment_v1','friend_activity_page_v1','get_manga_chapter_status','get_media_availability_status','get_media_ladder','get_provider_availability_refresh_queue_summary','home_bundle_v1','home_events_page_v1','home_pending_page_v1','import_job_status_v1','join_club','leave_club','legacy_unit_bridge_trigger_v1','list_account_write_lock','list_disclosure_signal_v1','list_entry_revision_fence','list_unit_owner_guard_v1','publish_mapping_revision','recommend_ids_similar_to_seeds','record_outbound_link','record_taste_deck_signal','save_user_streaming_services','search_anime_page','search_manga_page','series_detail_bundle_v1','series_editions_page_v1','series_units_page_v1','shares_club_at_least','shares_club_with','start_library_import_v1','toggle_club_reaction','toggle_comment_reaction','undo_import_session','upsert_title_comment','upsert_title_comment_scoped_v1')),
'policies',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY tablename,policyname),'[]'::jsonb) FROM pg_policies x WHERE schemaname IN ('public','storage') AND (tablename IN ('account_deletion_barriers','adaptation_coverage','anime','anime_characters','anime_staff','anime_studios','anime_user_lists','artwork_materials','catalogue_units','chapters','club_activity_signals','club_members','club_membership_signals','concierge_events','detail_copy','episodes','external_links','feature_flag_overrides','feature_flags','home_publications','import_session_items','import_sessions','library_import_baselines','library_import_items','library_import_jobs','list_entry_tombstones','manga','manga_authors','manga_characters','manga_user_lists','mapping_revision_spans','mapping_revisions','mutation_receipts','mv_anime_trending','profiles','provider_entry_refs','realm_meta','release_events','series','series_enrichment_jobs','series_entry_spans','series_sections','streaming_services','theme_links','user_airing_next','user_series_intent','user_streaming_services') OR schemaname='storage')),
'grants',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY table_name,grantee,privilege_type),'[]'::jsonb) FROM information_schema.role_table_grants x WHERE table_schema='public' AND table_name IN ('account_deletion_barriers','adaptation_coverage','anime','anime_characters','anime_staff','anime_studios','anime_user_lists','artwork_materials','catalogue_units','chapters','club_activity_signals','club_members','club_membership_signals','concierge_events','detail_copy','episodes','external_links','feature_flag_overrides','feature_flags','home_publications','import_session_items','import_sessions','library_import_baselines','library_import_items','library_import_jobs','list_entry_tombstones','manga','manga_authors','manga_characters','manga_user_lists','mapping_revision_spans','mapping_revisions','mutation_receipts','mv_anime_trending','profiles','provider_entry_refs','realm_meta','release_events','series','series_enrichment_jobs','series_entry_spans','series_sections','streaming_services','theme_links','user_airing_next','user_series_intent','user_streaming_services') AND grantee IN ('anon','authenticated','service_role')),
'flags',(SELECT coalesce(jsonb_agg(to_jsonb(f)),'[]'::jsonb) FROM public.feature_flags f WHERE f.flag_name IN ('series_foundation_v1','series_home_native_v1','rag_assist_v1')),
'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'function',p.proname) ORDER BY c.relname,t.tgname),'[]'::jsonb) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND n.nspname='public' AND c.relname IN ('account_deletion_barriers','adaptation_coverage','anime','anime_characters','anime_staff','anime_studios','anime_user_lists','artwork_materials','catalogue_units','chapters','club_activity_signals','club_members','club_membership_signals','concierge_events','detail_copy','episodes','external_links','feature_flag_overrides','feature_flags','home_publications','import_session_items','import_sessions','library_import_baselines','library_import_items','library_import_jobs','list_entry_tombstones','manga','manga_authors','manga_characters','manga_user_lists','mapping_revision_spans','mapping_revisions','mutation_receipts','mv_anime_trending','profiles','provider_entry_refs','realm_meta','release_events','series','series_enrichment_jobs','series_entry_spans','series_sections','streaming_services','theme_links','user_airing_next','user_series_intent','user_streaming_services')),
'publication',(SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) FROM pg_publication_tables x WHERE pubname='supabase_realtime'),
'deletion_helper_md5',(SELECT md5(prosrc) FROM pg_proc WHERE oid=to_regprocedure('public._account_write_guard(text)'))
) AS backend_inventory; ROLLBACK;
